import{_ as a,o,c as t,ag as i}from"./chunks/framework.D9ghT4bC.js";const n="/Unciv/assets/show_whitespace.DZksfuxn.png",A="data:image/gif;base64,",m=JSON.parse('{"title":"Coding standards","description":"","frontmatter":{},"headers":[],"relativePath":"Developers/Coding-standards.md","filePath":"Developers/Coding-standards.md"}'),s={name:"Developers/Coding-standards.md"};function r(l,e,c,d,h,p){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="coding-standards" tabindex="-1">Coding standards <a class="header-anchor" href="#coding-standards" aria-label="Permalink to &quot;Coding standards&quot;">​</a></h1><p>As an open-source project, there will be a lot of eyes on our code.</p><p>The main purpose of having a coding standard is for the code to be as immediately readable as possible to as many potential contributors, and hence most of it focuses on defaulting to coding structures that exist in other similar languages (Java, C#) when possible.</p><h2 id="exit-early" tabindex="-1">Exit Early <a class="header-anchor" href="#exit-early" aria-label="Permalink to &quot;Exit Early&quot;">​</a></h2><p>Check conditions where the function should exit at the top, and just <code>return</code>.</p><p>This both reduces nesting and clarifies the flow of the function - &quot;if we got this far we don&#39;t need to worry about X&quot;</p><h2 id="don-t-use-let-and-in-multiline-functions" tabindex="-1">Don&#39;t use <code>.let{}</code> and <code>?:</code> in multiline functions <a class="header-anchor" href="#don-t-use-let-and-in-multiline-functions" aria-label="Permalink to &quot;Don&#39;t use `.let{}` and `?:` in multiline functions&quot;">​</a></h2><p>Kotlin is made greater for being strict with nullability. Don&#39;t let this fact confuse people new to it. These can be simply replaced by <code>if(x!=null)</code> which is much more readable. They all probably compile to the same bytecode anyway, so when in doubt - readability.</p><p>If it&#39;s a single-line function anyway, then fine, I won&#39;t be pedantic</p><h2 id="for-item-in-list-and-not-list-foreach" tabindex="-1"><code>for (item in list)</code> and not <code>list.forEach{}</code> <a class="header-anchor" href="#for-item-in-list-and-not-list-foreach" aria-label="Permalink to &quot;`for (item in list)` and not `list.forEach{}`&quot;">​</a></h2><p>For loops go waaaay back, forEach doesn&#39;t.</p><p>As above, if it&#39;s a single-line function I&#39;m less pedantic.</p><h2 id="avoid-premature-abstraction" tabindex="-1">Avoid premature abstraction <a class="header-anchor" href="#avoid-premature-abstraction" aria-label="Permalink to &quot;Avoid premature abstraction&quot;">​</a></h2><p>There&#39;s no need to create an interface if there is only one implementation of that interface. Doing so obfuscates the actual code that&#39;s running and increases the Time To Relevant Code. If abstraction becomes necessary later, we can always do it later.</p><h2 id="remove-trailing-space-before-commit-non-translation" tabindex="-1">Remove trailing space before commit (non-Translation) <a class="header-anchor" href="#remove-trailing-space-before-commit-non-translation" aria-label="Permalink to &quot;Remove trailing space before commit (non-Translation)&quot;">​</a></h2><p>Trailing spaces are indent characters represented as <code>..</code> at the start of line. Android Studio always defaults to create similar indents as previous lines. Thus on attempts to create a blank line (in a code block), it produces trailing space character. Unchecking <code>Remove trailing spaces on [..]</code> is necessary for translation part of project but these characters creates annoying code merges.</p><p>Settings &gt; Editor &gt; General &gt; Appearence &gt; Check <code>Show whitespaces</code> and remove the <code>..</code> characters. <img src="'+n+'" alt="image"><img src="'+A+'" alt="gif"></p>',17)])])}const f=a(s,[["render",r]]);export{m as __pageData,f as default};
